using System.Text.Json;
using Tertius.Demo;
using Tertius.Rendering;

namespace Tertius.Host.Tests;

public sealed class BoxCaptureObserver
{
    private static readonly JsonSerializerOptions HistoryJson = new()
    {
        NumberHandling = System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals
    };

    [Fact]
    public void WarmedCapturesAdvanceTheirSnapshotClockAndKeepTheirDrawHistory()
    {
        string checkout = Environment.GetEnvironmentVariable("TERTIUS_BOX_ROOT")
            ?? throw new InvalidOperationException("TERTIUS_BOX_ROOT is required.");
        string variant = Environment.GetEnvironmentVariable("TERTIUS_BOX_VARIANT")
            ?? throw new InvalidOperationException("TERTIUS_BOX_VARIANT is required.");
        string root = Path.Combine(checkout, "captures/ter-7tnv-box");
        foreach (string view in new[] { "terminal", "floor", "cabin" })
        {
            var probe = new ObservationPass();
            using var output = new StringWriter();
            using var error = new StringWriter();
            string script = view == "cabin" ? "ter-7tnv-box-cabin.json" : $"ter-7tnv-{view}.json";
            int code = ScriptCommand.Run(
                args: ["--script", Path.Combine(checkout, "scripts", script), "--headless", "--out",
                    Path.Combine(root, $"{variant}-observed-{view}")],
                scenes: DemoScenes.All, output: output, error: error,
                createRenderer: options =>
                {
                    File.WriteAllText(Path.Combine(root, $"{variant}-{view}-settings.json"), JsonSerializer.Serialize(new
                    {
                        options.Width, options.Height, options.WarmUpFrames, options.Validation,
                        options.Impostors, options.CapturesInFlight,
                        ScreenTrace = options.ScreenTrace.ToString(), Exposure = options.Exposure.ToString(),
                        EnvironmentMap = options.EnvironmentMap.ToString(), Bloom = options.Bloom.ToString(),
                        AntiAliasing = options.AntiAliasing.ToString(), Subsurface = options.Subsurface.ToString()
                    }));
                    VulkanRenderer renderer = VulkanRenderer.CreateHeadless(options);
                    renderer.Graph.Add(FrameGraph.Stage.Composite, probe);
                    return renderer;
                }
            );
            File.WriteAllText(Path.Combine(root, $"{variant}-{view}-history.json"), JsonSerializer.Serialize(probe.Rows, HistoryJson));
            code.Should().Be(ScriptCommand.Ok, error.ToString());
            probe.Indices.Should().Equal(Enumerable.Range(0, 34).Select(index => (long)index));
            probe.Resets.Count(reset => reset).Should().Be(1);
            probe.Times.Distinct().Should().HaveCount(2);
            (probe.Times[^1] - probe.Times[0]).Should().BeApproximately(1.0 / 60, 1e-10);
        }
    }

    private sealed class ObservationPass : RenderPass
    {
        public override string Name => "box capture history evidence";
        public List<object> Rows { get; } = [];
        public List<long> Indices { get; } = [];
        public List<bool> Resets { get; } = [];
        public List<double> Times { get; } = [];

        public override void Record(FrameContext context)
        {
            Indices.Add(context.History.DrawIndex);
            Resets.Add(context.History.Reset);
            Times.Add(context.Snapshot.Time);
            Rows.Add(new
            {
                context.Number, context.History.DrawIndex, context.History.Reset,
                SnapshotSeconds = context.Snapshot.Time, context.History.ExposureStep,
                context.Scene.MapCount,
                Chain = context.Snapshot.Chain.Select(frame => new
                {
                    frame.FrameId,
                    Axes = new[] { frame.Rotation.X, frame.Rotation.Y, frame.Rotation.Z, frame.Rotation.W }
                }).ToArray(),
                Boxes = Enumerable.Range(0, context.Scene.MapCount).Select(map =>
                {
                    GpuMapBox box = context.Scene.Constants.MapBoxes[map];
                    return new
                    {
                        Map = map,
                        Minimum = new[] { box.Minimum.X, box.Minimum.Y, box.Minimum.Z, box.Minimum.W },
                        Maximum = new[] { box.Maximum.X, box.Maximum.Y, box.Maximum.Z, box.Maximum.W }
                    };
                }).ToArray()
            });
        }
    }
}
